eng10Unit7.sourcePages.push(
{pdf:'10th english.pdf',pdfPage:77,printedPage:'70',title:'The Aged Mother writing, speaking and modal verbs',text:'Writing asks learners to analyze the last paragraph for theme/general subject, central thought and supporting details; discuss respect for elders/parents in relation to today’s youth in at least 100 words; and summarize the lesson. Speaking is a paired role-play offering/responding to greetings, compliments, invitations, introductions and farewells. Grammar A asks the function of modals in “May I use your mobile phone?”, “You mustn’t walk on grass”, and “He should come to the meetings on time.”'},
{pdf:'10th english.pdf',pdfPage:78,printedPage:'71',title:'Modal verb functions, exercise A continued',text:'Questions 4–9 test functions in “Can you help me with this exercise?”, “You needn’t take your umbrella. It isn’t raining”, “Could you say it again more slowly?”, the weather prediction for the beach, the dog’s habitual barking, and “Shall I help you with your luggage?”'},
{pdf:'10th english.pdf',pdfPage:79,printedPage:'72',title:'Modal verb exercise B and function reference table',text:'Five sentence-completion MCQs test advice (should see a doctor), requests (Could you take a message), possibility (might be Anam’s), past necessity (should have stayed home), and permission (can leave work). Teacher reference table lists modal functions: ability, possibility/probability, permission, request, offer, suggestion, strong advice/obligation, necessity, absence of necessity and prohibition.'},
{pdf:'10th english.pdf',pdfPage:80,printedPage:'73',title:'Regular and irregular verbs exercise',text:'A simple-past gap-fill narrates Tahir’s day using the verbs get, have, put, have, go, brush, comb, put, leave, take, have, get, get, enter, listen, hurry, be, eat, do, watch, have, meet, come, wash, brush, put, recite and fall.'}
);
eng10Unit7.sourcePages.push({pdf:'10th english.pdf',pdfPage:81,printedPage:'74',title:'The Aged Mother, writing, role-play and modal verb functions',text:'Writing prompts analyze theme, central thought and supporting details, discuss respect for elders in at least 100 words, and summarize the lesson. Paired role-play practices greetings, compliments, invitations, introductions and farewells. Modal questions A1–3 test permission, prohibition and advice.'},{pdf:'10th english.pdf',pdfPage:82,printedPage:'75',title:'Modal verb functions continued',text:'Modal items A4–9 test request, lack of necessity, polite request, prediction, habitual action and offer of help.'},{pdf:'10th english.pdf',pdfPage:83,printedPage:'76',title:'Modal verbs: completion and reference table',text:'Five completion questions test advice, request, possibility, past necessity and permission. Reference table groups modal functions into ability, possibility/probability, permission, request, offer, suggestion, strong advice/obligation, necessity, absence of necessity and prohibition.'},{pdf:'10th english.pdf',pdfPage:84,printedPage:'77',title:'Regular and irregular verbs, simple past',text:'Narrative gap-fill about Tahir’s daily routine; students put 28 parenthesized regular and irregular verbs into the simple past.'});
