eng10Unit10.exercise.grammarActivities[0].rule='An infinitive is a verb form that can be used as a noun, an adjective, or an adverb. Most infinitives begin with “to”. An infinitive phrase consists of an infinitive together with its modifiers and complements; the entire phrase may be used as a noun, an adjective, or an adverb.';
eng10Unit10.exercise.grammarActivities[0].examples=['To heal was the athlete’s first priority. (noun)','The player to watch this season is Afridi. (adjective)','This speech will be easy to memorize. (adverb)','To heal in shape requires dedication and discipline. (noun phrase)','The thing to do first is an activity you enjoy. (adjective phrase)','I came to Swat to see the art exhibition. (adverb phrase)'];
eng10Unit10.exercise.grammarActivities[0].exercises=[
 {q:'More than anything else, I wanted some time alone to read.',ans:'to read — adjective; it modifies “time”.'},
 {q:'My grandmother told me that we have been put on earth to share, to care, to give, and to receive.',ans:'to share, to care, to give, to receive — adverbial infinitives expressing purpose.'},
 {q:'The right to vote is very valuable.',ans:'to vote — adjective; it modifies “right”.'},
 {q:'I tried to call but the line was busy.',ans:'to call — noun; object of “tried”.'},
 {q:'To finish will be a relief.',ans:'To finish — noun; subject of the sentence.'},
 {q:'Do you agree with the decision to go?',ans:'to go — adjective; it modifies “decision”.'},
 {q:'The case will not be easy to solve.',ans:'to solve — adverbial; it completes “easy”.'},
 {q:'To fly, the wings must create more lift.',ans:'To fly — infinitive expressing purpose.'}
];
eng10Unit10.exercise.grammarActivities.push({topic:'Infinitive phrases: identify function (printed page 100, Exercise B)',sourcePdfPage:107,instructions:'Underline the infinitive phrases and tell whether each is used as a noun, adjective, or adverb.',exercises:[
 {q:'Sending her roses is a way to win her friendship.',ans:'to win her friendship — adjective phrase modifying “way”.'},
 {q:'The day to sleep in is Saturday.',ans:'to sleep in — adjective phrase modifying “day”.'},
 {q:'Javed is coming to discuss the problem with the boss.',ans:'to discuss the problem with the boss — adverb phrase of purpose.'},
 {q:'It is also possible to bring cookies rather than a cake.',ans:'to bring cookies rather than a cake — adjective phrase completing “possible”.'},
 {q:'Please write the numbers to win the lottery on this form.',ans:'to win the lottery — adverb phrase of purpose.'},
 {q:'The museum is fun to visit on a cold day.',ans:'to visit on a cold day — adjective phrase completing “fun”.'},
 {q:'The captain of the ship is the authority to obey at all times.',ans:'to obey at all times — adjective phrase modifying “authority”.'},
 {q:'Samia offered to think over the argument.',ans:'to think over the argument — noun phrase, object of “offered”.'}
]});
